const WORD_BY_RANK = {};
WORDS.forEach((w) => { WORD_BY_RANK[w.rank] = w; });

const STORAGE_KEY = "mil-palavras-progress-v1";
const SESSION_SIZE = 10;

const BOX_WEIGHTS = [7, 5, 3, 2, 1, 1];
const UNSEEN_WEIGHT = 9;

function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function todayStr() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function daysBetween(a, b) {
  const da = new Date(a + "T00:00:00");
  const db = new Date(b + "T00:00:00");
  return Math.round((db - da) / 86400000);
}

function defaultProgress() {
  return {
    stats: {},
    xp: 0,
    streakCount: 0,
    lastPracticeDate: null,
    totalSessions: 0,
    totalAnswered: 0,
    totalCorrect: 0,
  };
}

function getDistractors(pool, target, field, count) {
  const seen = new Set([target[field]]);
  const candidates = pool.filter((w) => {
    if (w.rank === target.rank) return false;
    if (seen.has(w[field])) return false;
    return true;
  });
  const shuffled = shuffle(candidates);
  const picked = [];
  for (const c of shuffled) {
    if (picked.length >= count) break;
    if (seen.has(c[field])) continue;
    seen.add(c[field]);
    picked.push(c);
  }
  return picked;
}

function buildQuestion(target, direction, words) {
  const field = direction === "w2m" ? "meaning" : "word";
  const distractors = getDistractors(words, target, field, 3);
  const optionSource = shuffle([target, ...distractors]);
  const options = optionSource.map((w) => ({ rank: w.rank, text: w[field] }));
  return { rank: target.rank, direction, item: target, options };
}

function buildSession(words, stats, size) {
  const pool = [];
  words.forEach((w) => {
    const s = stats[w.rank];
    const box = s ? s.box : -1;
    const weight = box === -1 ? UNSEEN_WEIGHT : BOX_WEIGHTS[box] ?? 1;
    for (let i = 0; i < weight; i++) pool.push(w);
  });
  const shuffled = shuffle(pool);
  const chosen = [];
  const used = new Set();
  for (const w of shuffled) {
    if (chosen.length >= size) break;
    if (used.has(w.rank)) continue;
    used.add(w.rank);
    chosen.push(w);
  }
  return chosen.map((w) => buildQuestion(w, Math.random() < 0.5 ? "w2m" : "m2w", words));
}

function useProgress() {
  const [progress, setProgress] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      setProgress(raw ? { ...defaultProgress(), ...JSON.parse(raw) } : defaultProgress());
    } catch (e) {
      setProgress(defaultProgress());
    } finally {
      setLoading(false);
    }
  }, []);

  const persist = useCallback((next) => {
    setProgress(next);
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
    } catch (e) {
      // ignore persistence errors (e.g. private browsing), keep local state
    }
  }, []);

  return { progress, loading, persist };
}

function speak(text, rate) {
  try {
    if (!window.speechSynthesis) return false;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    const voices = window.speechSynthesis.getVoices();
    const voice =
      voices.find((v) => v.lang === "pt-BR") ||
      voices.find((v) => v.lang && v.lang.startsWith("pt"));
    if (voice) u.voice = voice;
    u.lang = "pt-BR";
    u.rate = rate || 0.92;
    window.speechSynthesis.speak(u);
    return true;
  } catch (e) {
    return false;
  }
}

function SpeakerButton({ text, size, label }) {
  const [supported, setSupported] = useState(true);
  useEffect(() => {
    setSupported(typeof window !== "undefined" && !!window.speechSynthesis);
  }, []);
  return (
    <button
      type="button"
      className="mp-speaker-btn"
      style={size ? { width: size, height: size } : undefined}
      onClick={(e) => {
        e.stopPropagation();
        speak(text);
      }}
      disabled={!supported}
      aria-label={label || `${text} を発音`}
      title={supported ? "発音を聞く" : "この端末では音声再生に対応していません"}
    >
      <Volume2 size={size ? Math.round(size * 0.52) : 18} />
    </button>
  );
}

function MasteryBars({ stats }) {
  const counts = [0, 0, 0, 0, 0, 0];
  let unseen = WORDS.length;
  Object.values(stats).forEach((s) => {
    if (s && typeof s.box === "number") {
      counts[s.box] = (counts[s.box] || 0) + 1;
      unseen -= 1;
    }
  });
  const total = WORDS.length;
  const segments = [
    { label: "未学習", value: unseen, cls: "seg-unseen" },
    { label: "box0-1", value: counts[0] + counts[1], cls: "seg-low" },
    { label: "box2-3", value: counts[2] + counts[3], cls: "seg-mid" },
    { label: "box4-5", value: counts[4] + counts[5], cls: "seg-high" },
  ];
  return (
    <div className="mp-mastery">
      <div className="mp-mastery-track">
        {segments.map((s) => (
          <div
            key={s.label}
            className={`mp-mastery-seg ${s.cls}`}
            style={{ width: `${(s.value / total) * 100}%` }}
            title={`${s.label}: ${s.value}語`}
          />
        ))}
      </div>
      <div className="mp-mastery-legend">
        <span><i className="dot dot-high" />定着 {counts[4] + counts[5]}</span>
        <span><i className="dot dot-mid" />練習中 {counts[2] + counts[3]}</span>
        <span><i className="dot dot-low" />初期 {counts[0] + counts[1]}</span>
        <span><i className="dot dot-unseen" />未学習 {unseen}</span>
      </div>
    </div>
  );
}

function HomeScreen({ progress, onStart }) {
  const masteredCount = Object.values(progress.stats).filter((s) => s.box >= 4).length;
  const startedCount = Object.keys(progress.stats).length;
  const accuracy = progress.totalAnswered > 0
    ? Math.round((progress.totalCorrect / progress.totalAnswered) * 100)
    : null;

  return (
    <div className="mp-screen mp-home">
      <div className="mp-tile-corner mp-tile-tl" aria-hidden="true" />
      <div className="mp-tile-corner mp-tile-tr" aria-hidden="true" />
      <header className="mp-home-header">
        <p className="mp-eyebrow">Português para o dia a dia</p>
        <h1 className="mp-title">Mil Palavras</h1>
        <p className="mp-subtitle">頻出ポルトガル語 1〜1000位を、意味と単語のクイズで覚える</p>
      </header>

      <div className="mp-stat-row">
        <div className="mp-stat-card">
          <Flame size={20} className="mp-stat-icon flame" />
          <div>
            <div className="mp-stat-num">{progress.streakCount}</div>
            <div className="mp-stat-label">日連続</div>
          </div>
        </div>
        <div className="mp-stat-card">
          <Star size={20} className="mp-stat-icon star" />
          <div>
            <div className="mp-stat-num">{progress.xp}</div>
            <div className="mp-stat-label">XP</div>
          </div>
        </div>
        <div className="mp-stat-card">
          <Trophy size={20} className="mp-stat-icon trophy" />
          <div>
            <div className="mp-stat-num">{masteredCount}<span className="mp-stat-denom">/{WORDS.length}</span></div>
            <div className="mp-stat-label">定着済み</div>
          </div>
        </div>
      </div>

      <div className="mp-panel">
        <div className="mp-panel-row">
          <span className="mp-panel-label">進捗 (全{WORDS.length}語中 {startedCount}語に着手)</span>
          {accuracy !== null && <span className="mp-panel-label">正答率 {accuracy}%</span>}
        </div>
        <MasteryBars stats={progress.stats} />
      </div>

      <button className="mp-cta" onClick={onStart}>
        <span>練習をはじめる ({SESSION_SIZE}問)</span>
        <ChevronRight size={20} />
      </button>

      <p className="mp-footnote">範囲: 頻出度 1〜1000位・意味↔単語の選択式</p>
    </div>
  );
}

function QuestionCard({ question, onAnswer, selected, revealed }) {
  const { item, direction, options } = question;
  const promptText = direction === "w2m" ? item.word : item.meaning;
  const isWordPrompt = direction === "w2m";

  return (
    <div className="mp-card">
      <div className="mp-card-kicker">{isWordPrompt ? "この単語の意味は？" : "この意味の単語は？"}</div>
      <div className="mp-card-prompt">
        <div className={isWordPrompt ? "mp-prompt-word" : "mp-prompt-meaning"}>
          {promptText}
          {isWordPrompt && <SpeakerButton text={item.word} size={34} />}
        </div>
        {isWordPrompt && <div className="mp-prompt-ipa">[{item.ipa}]</div>}
      </div>

      <div className="mp-options">
        {options.map((opt) => {
          let cls = "mp-option";
          if (revealed) {
            if (opt.rank === item.rank) cls += " correct";
            else if (opt.rank === selected) cls += " wrong";
            else cls += " dim";
          } else if (opt.rank === selected) {
            cls += " picked";
          }
          return (
            <button
              key={opt.rank}
              className={cls}
              onClick={() => !revealed && onAnswer(opt.rank)}
              disabled={revealed}
            >
              <span>{opt.text}</span>
              {revealed && opt.rank === item.rank && <Check size={18} />}
              {revealed && opt.rank === selected && opt.rank !== item.rank && <X size={18} />}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function RevealPanel({ question, correct, onNext, isLast }) {
  const { item } = question;
  return (
    <div className={`mp-reveal ${correct ? "is-correct" : "is-wrong"}`}>
      <div className="mp-reveal-head">
        {correct ? <Check size={18} /> : <X size={18} />}
        <span>{correct ? "正解！" : "残念、不正解"}</span>
      </div>
      <div className="mp-reveal-word">
        <span className="mp-reveal-word-text">{item.word}</span>
        <span className="mp-reveal-ipa">[{item.ipa}]</span>
        <SpeakerButton text={item.word} size={28} />
      </div>
      <div className="mp-reveal-meaning">{item.meaning}</div>
      {item.example_pt && (
        <div className="mp-reveal-example">
          <div className="mp-example-pt">
            {item.example_pt}
            <SpeakerButton text={item.example_pt} size={26} />
          </div>
          <div className="mp-example-jp">{item.example_jp}</div>
        </div>
      )}
      {item.note && <div className="mp-reveal-note">{item.note}</div>}
      <button className="mp-cta mp-cta-secondary" onClick={onNext}>
        <span>{isLast ? "結果を見る" : "次の問題"}</span>
        <ChevronRight size={18} />
      </button>
    </div>
  );
}

function PracticeScreen({ session, onFinish, onExit }) {
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState(null);
  const [revealed, setRevealed] = useState(false);
  const [results, setResults] = useState([]);

  const question = session[index];
  const isLast = index === session.length - 1;

  const handleAnswer = (rank) => {
    if (revealed) return;
    const correct = rank === question.item.rank;
    setSelected(rank);
    setRevealed(true);
    setResults((r) => [...r, { rank: question.item.rank, correct }]);
  };

  const handleNext = () => {
    if (isLast) {
      onFinish(results);
      return;
    }
    setIndex((i) => i + 1);
    setSelected(null);
    setRevealed(false);
  };

  return (
    <div className="mp-screen mp-practice">
      <div className="mp-progress-row">
        <button className="mp-icon-btn" onClick={onExit} aria-label="ホームに戻る">
          <Home size={18} />
        </button>
        <div className="mp-progress-track">
          <div className="mp-progress-fill" style={{ width: `${((index + (revealed ? 1 : 0)) / session.length) * 100}%` }} />
        </div>
        <span className="mp-progress-count">{index + 1}/{session.length}</span>
      </div>

      <QuestionCard question={question} onAnswer={handleAnswer} selected={selected} revealed={revealed} />

      {revealed && (
        <RevealPanel
          question={question}
          correct={results[results.length - 1]?.correct}
          onNext={handleNext}
          isLast={isLast}
        />
      )}
    </div>
  );
}

function SummaryScreen({ results, xpGained, streakCount, onRestart, onHome }) {
  const correctCount = results.filter((r) => r.correct).length;
  const total = results.length;
  const pct = Math.round((correctCount / total) * 100);
  return (
    <div className="mp-screen mp-summary">
      <div className="mp-summary-badge">
        <Trophy size={40} />
      </div>
      <h2 className="mp-summary-title">セット完了！</h2>
      <div className="mp-summary-stats">
        <div className="mp-summary-stat">
          <div className="mp-summary-num">{correctCount}/{total}</div>
          <div className="mp-summary-label">正解</div>
        </div>
        <div className="mp-summary-stat">
          <div className="mp-summary-num">{pct}%</div>
          <div className="mp-summary-label">正答率</div>
        </div>
        <div className="mp-summary-stat">
          <div className="mp-summary-num">+{xpGained}</div>
          <div className="mp-summary-label">獲得XP</div>
        </div>
      </div>
      <div className="mp-summary-streak">
        <Flame size={18} className="mp-stat-icon flame" />
        <span>連続 {streakCount} 日</span>
      </div>
      <div className="mp-summary-actions">
        <button className="mp-cta" onClick={onRestart}>
          <RotateCcw size={18} />
          <span>もう1セット</span>
        </button>
        <button className="mp-cta mp-cta-ghost" onClick={onHome}>
          <Home size={18} />
          <span>ホームへ</span>
        </button>
      </div>
    </div>
  );
}

export default function MilPalavras() {
  const { progress, loading, persist } = useProgress();
  const [view, setView] = useState("home");
  const [session, setSession] = useState(null);
  const [lastResults, setLastResults] = useState([]);
  const [lastXpGained, setLastXpGained] = useState(0);

  useEffect(() => {
    if (typeof window !== "undefined" && window.speechSynthesis) {
      const load = () => window.speechSynthesis.getVoices();
      load();
      window.speechSynthesis.onvoiceschanged = load;
    }
  }, []);

  const startSession = useCallback(() => {
    if (!progress) return;
    const s = buildSession(WORDS, progress.stats, SESSION_SIZE);
    setSession(s);
    setView("practice");
  }, [progress]);

  const finishSession = useCallback((results) => {
    if (!progress) return;
    const nextStats = { ...progress.stats };
    results.forEach(({ rank, correct }) => {
      const prev = nextStats[rank] || { box: -1, seen: 0, correct: 0, incorrect: 0 };
      const box = correct ? Math.min((prev.box < 0 ? 0 : prev.box) + 1, 5) : 0;
      nextStats[rank] = {
        box,
        seen: (prev.seen || 0) + 1,
        correct: (prev.correct || 0) + (correct ? 1 : 0),
        incorrect: (prev.incorrect || 0) + (correct ? 0 : 1),
        lastSeen: Date.now(),
      };
    });

    const correctCount = results.filter((r) => r.correct).length;
    const xpGained = correctCount * 10 + 20;

    const today = todayStr();
    let streakCount = progress.streakCount;
    if (!progress.lastPracticeDate) {
      streakCount = 1;
    } else {
      const diff = daysBetween(progress.lastPracticeDate, today);
      if (diff === 0) streakCount = progress.streakCount || 1;
      else if (diff === 1) streakCount = (progress.streakCount || 0) + 1;
      else streakCount = 1;
    }

    const next = {
      ...progress,
      stats: nextStats,
      xp: progress.xp + xpGained,
      streakCount,
      lastPracticeDate: today,
      totalSessions: progress.totalSessions + 1,
      totalAnswered: progress.totalAnswered + results.length,
      totalCorrect: progress.totalCorrect + correctCount,
    };
    persist(next);
    setLastResults(results);
    setLastXpGained(xpGained);
    setView("summary");
  }, [progress, persist]);

  if (loading || !progress) {
    return (
      <div className="mp-root">
        <MilPalavrasStyles />
        <div className="mp-screen mp-loading">
          <div className="mp-loading-spinner" />
          <p>読み込み中…</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mp-root">
      <MilPalavrasStyles />
      {view === "home" && <HomeScreen progress={progress} onStart={startSession} />}
      {view === "practice" && session && (
        <PracticeScreen session={session} onFinish={finishSession} onExit={() => setView("home")} />
      )}
      {view === "summary" && (
        <SummaryScreen
          results={lastResults}
          xpGained={lastXpGained}
          streakCount={progress.streakCount}
          onRestart={startSession}
          onHome={() => setView("home")}
        />
      )}
    </div>
  );
}

